<script lang="ts">
  import { onMount } from 'svelte';
  import type { ApiClient } from '../api/client';
  import { createCameraStore, describeCameraMedia, type CamerasState } from '../stores/cameras';
  import HlsPlayer from './HlsPlayer.svelte';

  let { client, owner = false }: { client: ApiClient; owner?: boolean } = $props();
  const createStore = () => createCameraStore(client);
  const store = createStore();
  let ui: CamerasState = $state(store.state);
  const selected = $derived(ui.items.find((item) => item.camera_id === ui.selected) ?? null);
  const confidence = (value: number) => `${Math.round(value * 100)}% confident`;
  const health = (value: string) => value[0]?.toUpperCase() + value.slice(1);
  const streams = $derived(selected?.streams ?? []);
  const mediaOff = $derived(describeCameraMedia(ui.media));
  const setupNote = $derived(ui.media && !ui.media.setup_available ? ui.media.setup_detail : '');
  // Only the owner can add or remove a camera, and only when the service says setup works on this machine.
  const canAdd = $derived(owner && !!ui.media && ui.media.setup_available);
  let address = $state(''); let username = $state(''); let password = $state(''); let cameraName = $state(''); let allowBasic = $state(false);
  let confirmingRemove = $state(false);
  let lastSelected: string | null = null;
  $effect(() => { const current = ui.selected; if (current !== lastSelected) { lastSelected = current; confirmingRemove = false; } });
  async function submitAdd(event: SubmitEvent) {
    event.preventDefault();
    const input = { address, username, password, ...(cameraName.trim() ? { name: cameraName.trim() } : {}), ...(allowBasic ? { allow_basic: true } : {}) };
    // The password is never kept: the field is emptied the moment the form is sent, whatever the outcome.
    password = '';
    if (await store.add(input)) { address = ''; username = ''; cameraName = ''; allowBasic = false; }
  }
  async function removeSelected() {
    if (!selected) return;
    const done = await store.remove(selected.camera_id);
    if (done) confirmingRemove = false;
  }
  onMount(() => { const unsubscribe = store.subscribe((next) => ui = next); void store.load(); return () => { unsubscribe(); void store.dispose(); }; });
</script>

<section class="cameras-view" aria-labelledby="cameras-heading">
  <div class="view-heading camera-heading"><div><p class="kicker">CAMERAS / PRIVATE VIEW</p><h1 id="cameras-heading">Watch the threshold.</h1><p class="muted">See only verified camera details. Video stays inside your local service.</p></div><span class="camera-beacon" aria-hidden="true"><i></i> LIVE SIGNAL</span></div>
  {#if mediaOff}<div class="camera-state media-off" role="status"><strong>{mediaOff.title}.</strong> {mediaOff.action}</div>{/if}
  {#if canAdd}<section class="camera-add" aria-labelledby="camera-add-heading"><h2 id="camera-add-heading">Add a camera</h2><p class="muted">Enter the camera's address on your network and the user name and password you use to sign in to it. The password is sent to NeonHearth once and kept in this computer's secure credential store; it is never shown again.</p>
    <form class="camera-add-form" onsubmit={submitAdd}>
      <label class="search"><span>Camera address</span><input type="text" inputmode="decimal" autocomplete="off" spellcheck="false" maxlength="64" placeholder="192.168.1.50" bind:value={address} required /></label>
      <div class="camera-add-pair"><label class="search"><span>User name</span><input type="text" autocomplete="off" maxlength="128" bind:value={username} required /></label><label class="search"><span>Password</span><input type="password" autocomplete="new-password" maxlength="256" bind:value={password} required /></label></div>
      <label class="search"><span>Name (optional)</span><input type="text" maxlength="64" placeholder="Front porch" bind:value={cameraName} /></label>
      <label class="camera-basic"><input type="checkbox" bind:checked={allowBasic} /><span><strong>Allow less secure sign-in (Basic)</strong><small>Basic sends the camera's password without protection on your home network, so leave it off unless the camera cannot sign in any other way.</small></span></label>
      {#if ui.addError}<p class="camera-add-error" role="alert">{ui.addError}</p>{/if}
      <button type="submit" class="camera-add-submit" disabled={ui.adding}>{ui.adding ? 'Adding…' : 'Add camera'}</button>
    </form></section>{/if}
  {#if ui.loading}<div class="camera-state" role="status">Reading camera inventory…</div>{:else if ui.error && ui.items.length === 0}<div class="camera-state error" role="alert">{ui.error} <button type="button" class="camera-retry" onclick={() => void store.load()}>Retry</button></div>{:else if ui.items.length === 0}<div class="empty-state"><span class="empty-icon" aria-hidden="true">□</span><div><strong>No verified cameras yet</strong><p class="muted">When a camera earns enough evidence, it will appear here.</p>{#if setupNote}<p class="muted">{setupNote}</p>{/if}</div></div>{:else}
    {#if ui.unreadable > 0}<div class="camera-state partial" role="status">{ui.unreadable} camera{ui.unreadable === 1 ? '' : 's'} could not be read this time. <button type="button" class="camera-retry" onclick={() => void store.load()}>Retry</button></div>{/if}
    {#if ui.error}<div class="camera-state error" role="alert">{ui.error}</div>{/if}
    <div class="camera-grid" aria-label="Verified cameras">{#each ui.items as item}<button class:active={item.camera_id === ui.selected} class="camera-card" type="button" aria-pressed={item.camera_id === ui.selected} onclick={() => store.select(item.camera_id)}><span class="camera-eye" aria-hidden="true">◉</span><span><strong>{item.inventory?.manufacturer && item.inventory?.model ? `${item.inventory.manufacturer} ${item.inventory.model}` : 'Verified camera'}</strong><small>{item.classification.replaceAll('_', ' ')}</small></span><span class="camera-card-status {item.health}">{health(item.health)}</span><span class="camera-confidence">{confidence(item.confidence)}</span></button>{/each}</div>
    {#if selected}<article class="camera-console"><div class="camera-console-head"><div><p class="kicker">CAMERA STATUS</p><h2>{selected.inventory?.manufacturer && selected.inventory?.model ? `${selected.inventory.manufacturer} ${selected.inventory.model}` : 'Verified camera'}</h2></div><span class="health-chip {selected.health}"><i></i>{health(selected.health)}</span></div><div class="camera-stage">{#if ui.session}<HlsPlayer playlistUrl={ui.session.playlistUrl} authorize={client.authorizeCameraMediaXhr} />{:else if ui.snapshotUrl}<img src={ui.snapshotUrl} alt="Latest camera snapshot" />{:else}<div class="live-fallback"><span aria-hidden="true">◌</span><strong>{mediaOff ? 'Live view is off on this machine' : streams.length ? 'Live view is ready' : 'Live view needs a stream selected'}</strong><p>{mediaOff ? 'See the notice above for what to fix.' : streams.length ? 'Start a local live view when you are ready.' : 'Snapshot capture remains available while the collector shares no stream selection.'}</p></div>{/if}</div><div class="camera-actions"><button type="button" onclick={() => store.snapshot(selected.camera_id)}>Capture snapshot</button>{#if streams.length}<button type="button" onclick={() => store.startSession(selected.camera_id, streams[0].stream_id)}>Start live view</button>{/if}{#if ui.session}<button class="quiet-action" type="button" onclick={() => store.closeSession()}>Close live view</button>{/if}{#if owner}{#if confirmingRemove}<span class="remove-confirm" role="group" aria-label="Confirm removing this camera"><span>Remove this camera and its saved password?</span><button class="danger-action" type="button" disabled={ui.removing !== null} onclick={removeSelected}>{ui.removing !== null ? 'Removing…' : 'Yes, remove it'}</button><button class="quiet-action" type="button" disabled={ui.removing !== null} onclick={() => confirmingRemove = false}>Keep it</button></span>{:else}<button class="quiet-action danger-text" type="button" onclick={() => confirmingRemove = true}>Remove camera</button>{/if}{/if}</div>{#if ui.removeError}<p class="camera-add-error" role="alert">{ui.removeError}</p>{/if}{#if ui.session}<p class="live-session" aria-live="polite">Live session is active. Your browser will use the collector-generated playlist.</p>{/if}<dl class="camera-facts"><div><dt>Confidence</dt><dd>{confidence(selected.confidence)}</dd></div><div><dt>Inventory health</dt><dd>{selected.inventory ? health(selected.inventory.health) : 'Unavailable'}</dd></div><div><dt>Owner serial</dt><dd>{selected.inventory?.serial ?? 'Unavailable'}</dd></div><div><dt>Firmware</dt><dd>{selected.inventory?.firmware ?? 'Unavailable'}</dd></div></dl></article>{/if}
  {/if}
</section>

<style>
  .camera-heading{display:flex;justify-content:space-between;gap:18px}.camera-beacon,.health-chip,.camera-card-status,.camera-confidence{font:10px var(--font-mono);text-transform:uppercase;letter-spacing:.08em}.camera-beacon{align-self:flex-end;color:var(--accent)}.camera-beacon i,.health-chip i{display:inline-block;width:8px;height:8px;margin-right:6px;border-radius:50%;background:var(--accent);box-shadow:0 0 12px var(--accent);animation:beacon 1.8s ease-in-out infinite}.camera-state{margin-top:28px;padding:18px;border:1px dashed var(--line-strong);color:var(--muted-strong)}.camera-state.error{border-color:var(--pink);color:#ffb4cc}.camera-state.partial{border-color:var(--gold);color:#ffe0a3;margin-top:14px}.camera-state.media-off{border-color:var(--gold);color:#ffe0a3}.camera-state.media-off strong{color:var(--ink)}.camera-retry{margin-left:10px;min-height:38px;padding:7px 12px;border:1px solid var(--accent);border-radius:5px;background:transparent;color:var(--accent);font:600 12px var(--font-display);cursor:pointer}.camera-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:11px;margin:27px 0 14px}.camera-card{min-width:0;display:grid;grid-template-columns:26px minmax(0,1fr) auto;gap:9px;align-items:center;padding:15px;border:1px solid var(--line-mid);border-radius:8px;background:var(--surface);color:var(--ink);text-align:left;cursor:pointer}.camera-card.active{border-color:var(--accent);box-shadow:inset 0 0 22px color-mix(in srgb, var(--accent) 8%, transparent)}.camera-card strong,.camera-card small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.camera-card small{margin-top:4px;color:var(--muted)}.camera-eye{color:var(--accent);font-size:20px}.camera-card-status{color:var(--accent)}.camera-card-status.degraded{color:var(--gold)}.camera-card-status.unknown{color:var(--muted)}.camera-confidence{grid-column:2/-1;color:var(--muted-strong)}.camera-console{padding:20px;border:1px solid var(--line-mid);border-radius:12px;background:linear-gradient(120deg,var(--surface),#0a2029)}.camera-console-head{display:flex;justify-content:space-between;gap:12px;align-items:start}.camera-console h2{margin:5px 0 0;font:600 21px var(--font-display)}.health-chip{padding:7px 9px;border:1px solid var(--accent);color:var(--accent);border-radius:4px}.health-chip.degraded{border-color:var(--gold);color:var(--gold)}.health-chip.unknown{border-color:var(--muted);color:var(--muted)}.camera-stage{min-height:220px;margin:19px 0;border:1px solid var(--line);border-radius:7px;background:radial-gradient(circle at 50% 35%,#133e48,transparent 55%),var(--bg);display:grid;place-items:center;overflow:hidden}.camera-stage img{width:100%;height:100%;max-height:420px;object-fit:contain}.live-fallback{max-width:330px;padding:22px;text-align:center}.live-fallback span{display:block;margin-bottom:11px;color:var(--blue);font-size:34px}.live-fallback strong{display:block}.live-fallback p{color:var(--muted);font-size:12px;line-height:1.5}.camera-actions{display:flex;flex-wrap:wrap;gap:9px}.camera-actions button{min-height:44px;padding:10px 14px;border:1px solid var(--accent);border-radius:5px;color:var(--accent-ink);background:var(--accent);font:700 12px var(--font-display);cursor:pointer}.camera-actions .quiet-action{color:var(--ink);border-color:var(--line-strong);background:transparent}.live-session{color:var(--accent);font-size:12px}.camera-facts{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0 0}.camera-facts div{min-width:0;padding-top:11px;border-top:1px solid var(--line-mid)}.camera-facts dt{color:var(--muted);font:10px var(--font-mono);text-transform:uppercase}.camera-facts dd{margin:5px 0 0;overflow-wrap:anywhere;color:var(--ink);font-size:12px}@keyframes beacon{50%{opacity:.4;transform:scale(.65)}}@media(max-width:850px){.camera-heading{display:block}.camera-beacon{display:inline-block;margin-top:16px}.camera-grid{grid-template-columns:1fr}.camera-console{padding:15px}.camera-facts{grid-template-columns:1fr 1fr}.camera-stage{min-height:190px}.camera-actions button{flex:1 1 160px}}@media(prefers-reduced-motion:reduce){.camera-beacon i,.health-chip i{animation:none}}
  .camera-add{margin-top:28px;padding:20px;border:1px solid var(--line-mid);border-radius:var(--radius-lg);background:var(--surface);display:grid;gap:12px}.camera-add h2{margin:0;font:600 17px var(--font-display)}.camera-add .muted{margin:0}.camera-add-form{display:grid;gap:10px}.camera-add-form .search{margin:0}.camera-add-pair{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.camera-basic{display:flex;gap:10px;align-items:flex-start;color:var(--muted-strong);font-size:12px;line-height:1.45}.camera-basic input{margin-top:3px;accent-color:var(--accent)}.camera-basic strong,.camera-basic small{display:block}.camera-basic small{margin-top:3px;color:var(--muted)}.camera-add-error{margin:0;padding:9px;border:1px solid var(--risk);border-radius:var(--radius-sm);color:var(--risk);font:11px var(--font-mono)}.camera-add-submit{justify-self:start;min-height:44px;padding:10px 14px;border:1px solid var(--accent);border-radius:var(--radius-sm);background:var(--accent);color:var(--accent-ink);font:700 12px var(--font-display);cursor:pointer}.camera-add-submit:disabled,.camera-actions button:disabled{opacity:.5;cursor:not-allowed}.camera-actions .danger-text{color:var(--risk);border-color:var(--risk)}.remove-confirm{display:inline-flex;flex-wrap:wrap;gap:9px;align-items:center;font-size:12px;color:var(--muted-strong)}.camera-actions .danger-action{color:var(--ink);border-color:var(--risk);background:var(--risk)}
</style>
